for record in env['library.borrowing'].search([
    ('state', '=', 'borrowed'),
    ('due_date', '<', fields.Date.today()),
]):
    overdue_days = (fields.Date.today() - record.due_date).days
    record.write({
        'state': 'overdue',
        'fine_amount': overdue_days * record.fine_per_day,
    })

records = env['library.borrowing'].search([
    ('state', '=', 'overdue'),
    ('member_id.email', '!=', False),
])
template = env.ref('library_management.email_template_overdue_notice', raise_if_not_found=False)
if template:
    for rec in records:
        template.send_mail(rec.id, force_send=True)
